module freq_divbyeven #(
    parameter NUM_DIV = 6
) (
    input clk,
    input rst_n,
    output reg clk_div
);

    reg [3:0] cnt;

    // Ensure NUM_DIV is even and within valid range
    initial begin
        if (NUM_DIV < 2 || NUM_DIV > 32 || NUM_DIV[0] != 0) begin
            $display("Error: NUM_DIV must be even and between 2 and 32");
            $finish;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt <= 4'b0;
            clk_div <= 1'b0;
        end else begin
            if (cnt < (NUM_DIV / 2 - 1)) begin
                cnt <= cnt + 1;
            end else begin
                cnt <= 4'b0;
                clk_div <= ~clk_div;
            end
        end
    end

endmodule

