module freq_divbyodd #(
    parameter NUM_DIV = 5
) (
    input clk,
    input rst_n,
    output clk_div
);

    reg [31:0] cnt1, cnt2;
    reg clk_div1, clk_div2;

    // Counter for positive edge divider
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt1 <= 0;
            clk_div1 <= 1;
        end else begin
            if (cnt1 == NUM_DIV - 1) begin
                cnt1 <= 0;
                clk_div1 <= 1;
            end else begin
                cnt1 <= cnt1 + 1;
                if (cnt1 < (NUM_DIV-1)/2)
                    clk_div1 <= 1;
                else
                    clk_div1 <= 0;
            end
        end
    end

    // Counter for negative edge divider
    always @(negedge clk or negedge rst_n) begin
        if (!rst_n) begin
            cnt2 <= 0;
            clk_div2 <= 1;
        end else begin
            if (cnt2 == NUM_DIV - 1) begin
                cnt2 <= 0;
                clk_div2 <= 1;
            end else begin
                cnt2 <= cnt2 + 1;
                if (cnt2 < (NUM_DIV-1)/2)
                    clk_div2 <= 1;
                else
                    clk_div2 <= 0;
            end
        end
    end

    assign clk_div = clk_div1 | clk_div2;

endmodule

